225	    /// `ObjectFlags`: a class or interface type, an instantiation of one (a reference), a tuple, a mapped type.
226	    pub(crate) const OBJECT_CLASS: u64 = 1;
227	    pub(crate) const OBJECT_INTERFACE: u64 = 2;
228	    pub(crate) const OBJECT_REFERENCE: u64 = 4;
229	    /// `TypeFormatFlags` for `typeToString`: `NoTruncation`, `UseAliasDefinedOutsideCurrentScope`,
230	    /// `AllowUniqueESSymbolType` (the last two are what the checker uses when no flags are given) and `InTypeAlias`.
231	    pub(crate) const PRINT_EXPANDED: u64 = 1 | 16384 | 1_048_576 | 8_388_608;
232	    /// `TupleElementFlags`.
233	    pub(crate) const ELEMENT_OPTIONAL: u64 = 2;
234	    pub(crate) const ELEMENT_REST: u64 = 4;
235	    pub(crate) const ELEMENT_VARIADIC: u64 = 8;
236	}
