243	/// One `tsc --api` session bound to a snapshot and project.
244	pub(crate) struct Rpc {
245	    client: Client,
246	    deadline: Duration,
247	    snapshot: u64,
248	    project: String,
249	    /// Every call and its answer, when the caller asked to record a replay fixture.
250	    recording: Option<Mutex<Vec<Value>>>,
251	    calls: Mutex<BTreeMap<String, u64>>,
252	}
