329	    /// The recorded calls as a JSON array, or `None` when recording was off.
330	    pub(crate) fn recording(&self) -> Option<Value> {
331	        let log = self.recording.as_ref()?.lock().ok()?;
332	        Some(Value::Array(log.clone()))
333	    }
