362	    /// A request about this snapshot and project, its answer left as text.
363	    async fn scoped_text(&self, method: &str, extra: Value) -> Result<Box<RawValue>, CallError> {
364	        let mut params = json!({ "snapshot": self.snapshot, "project": self.project });
365	        if let (Some(base), Value::Object(extra)) = (params.as_object_mut(), extra) {
366	            base.extend(extra);
367	        }
368	        self.call(method, params).await
369	    }
