426	    /// Whether each property is declared `readonly`, in one round trip.
427	    pub(crate) async fn readonly_symbols(&self, symbols: &[&Value]) -> Result<Vec<bool>, CallError> {
428	        let requests = symbols.iter().map(|symbol| ("isReadonlySymbol", json!({ "symbol": symbol }))).collect();
429	        self.batch(requests).await?.iter().map(|answer| decode(answer)).collect()
430	    }
431	
432	    /// Several requests in one round trip. A request the checker rejects fails the batch: nothing here asks for one
433	    /// that may legitimately fail.
434	    pub(crate) async fn batch(&self, requests: Vec<(&str, Value)>) -> Result<Vec<Box<RawValue>>, CallError> {
435	        let wanted = requests.len();
436	        let scoped: Vec<Value> = requests
437	            .into_iter()
438	            .map(|(method, mut params)| {
439	                if let Value::Object(map) = &mut params {
440	                    map.insert("snapshot".to_string(), json!(self.snapshot));
441	                    map.insert("project".to_string(), json!(self.project));
442	                }
443	                json!({ "method": method, "params": params })
444	            })
445	            .collect();
446	        let mut answers = Vec::with_capacity(wanted);
447	        let mut token: Option<String> = None;
448	        loop {
449	            let mut params = json!({ "requests": scoped });
450	            if let (Some(token), Some(map)) = (&token, params.as_object_mut()) {
451	                map.insert("continuationToken".to_string(), json!(token));
452	            }
453	            let page: BatchPage = decode(&self.call("batchRequests", params).await?)?;
454	            for response in page.responses {
455	                if let Some(error) = response.error {
456	                    return Err(CallError::Rejected(error));
457	                }
458	                answers.push(response.result.unwrap_or_else(|| RawValue::NULL.to_owned()));
459	            }
460	            match page.continuation_token {
461	                Some(next) => token = Some(next),
462	                None => break,
463	            }
464	        }
465	        if answers.len() != wanted {
466	            return Err(CallError::Rejected(format!("a batch of {wanted} requests got {} answers", answers.len())));
467	        }
468	        Ok(answers)
469	    }
