501	        let mut answers = self.batch(requests).await?.into_iter();
502	        let mut next = || answers.next().ok_or_else(|| CallError::Rejected("a short batch".to_string()));
503	        Ok(ObjectMembers {
504	            calls: decode(&next()?)?,
505	            constructs: decode(&next()?)?,
506	            properties: decode(&next()?)?,
507	            indexes: decode(&next()?)?,
508	        })
509	    }
510	
511	    pub(crate) async fn alias_symbol(&self, type_id: u64) -> Result<Option<SymbolInfo>, CallError> {
512	        self.scoped("getAliasSymbolOfType", json!({ "objectId": type_id })).await
513	    }
