1	//! Experimental TypeScript 7.1 checker backend (`--experimental-semantic-types`).
2	//!
3	//! Spawns `tsc --api` (through `caliper-docgen-tsc-client`), asks it for the props of each component the structural
4	//! pass found, and hands `caliper-docgen-core` a [`SemanticOutcome`] to merge (ADR 0006, ADR 0007). It is always
5	//! compiled in and enabled at run time. Any failure to start or finish (no `tsc`, an unpinned version, a crash, a
6	//! timeout) yields an outcome with no components and one diagnostic, never an error: the structural result is
7	//! complete on its own.
8	//!
9	//! This slice answers function components exported by name or as `default`. Class components, overloaded or
10	//! generic components and union props types keep their structural result and say why.
11	
12	#![deny(missing_docs)]
13	
14	mod component;
15	mod convert;
16	mod locate;
17	mod on_demand;
18	mod printed;
19	mod rpc;
20	
21	pub use on_demand::{OnDemand, OnDemandConfig, Recycles};
22	
23	use std::sync::Arc;
24	use std::sync::atomic::{AtomicU64, Ordering};
25	use std::time::Duration;
26	
27	use caliper_docgen_core::types::ExtractionOutput;
28	use caliper_docgen_core::types::semantic::{PropInterner, SemanticComponent, SemanticFallback, SemanticOutcome};
29	use caliper_docgen_tsc_client::{Supervisor, SupervisorConfig};
30	use camino::{Utf8Path, Utf8PathBuf};
31	use rustc_hash::FxHashMap;
32	use tokio::sync::Semaphore;
33	use tokio::task::JoinSet;
34	
35	use crate::component::Answer;
36	use crate::convert::Converter;
37	use crate::rpc::{CallError, REQUESTS, Rpc};
38	
39	/// The builds whose protocol this backend was traced against: the `typescript` 7.1 series, from `7.1.0-beta` on, and
40	/// the `tsrs` builds listed exactly (`<tsrs version>-ts<typescript version>`), each only while its TypeScript part is
41	/// in the series above. The protocol has no version handshake, so the package's `package.json` version and the
42	/// initialize call that follows the spawn are the whole check; a build that fails either takes the structural result
43	/// with one warning.
44	pub const SUPPORTED_VERSIONS: &[&str] = &["7.1", "0.23.0-ts7.1.0-beta"];
45	
46	/// How many files are asked about at once. `tsc` answers requests one at a time; this keeps it from idling on round
47	/// trips.
48	const FILES_IN_FLIGHT: usize = 16;
49	
50	/// A component the structural pass found.
51	pub use caliper_docgen_core::types::semantic::SemanticTarget as Target;
52	
53	/// The components of `output`, in output order.
54	pub fn targets_of(output: &ExtractionOutput) -> Vec<Target> {
55	    output
56	        .components
57	        .values()
58	        .map(|entry| Target {
59	            file_path: entry.file_path.clone(),
60	            display_name: entry.display_name.clone(),
61	            exported: entry.exported,
62	            described: entry
63	                .props
64	                .values()
65	                .filter(|prop| !prop.description.is_empty())
66	                .map(|prop| prop.name.clone())
67	                .collect(),
68	            // The whole-project merge leaves `@types/react`'s props to the inheritance layers.
69	            react_wanted: Some(Default::default()),
70	        })
71	        .collect()
72	}
73	
74	/// One whole-project request to the checker: the components to answer for, and how to reach `tsc`. Built with
75	/// [`SemanticRequest::new`] and answered by [`resolve`].
76	#[derive(Debug, Clone)]
77	pub struct SemanticRequest {
78	    /// Where `tsc` finds `node_modules`; its `--cwd`, and where the search for `typescript` starts.
79	    pub project_root: Utf8PathBuf,
80	    /// A tsconfig whose compiler options the checker uses (read with `parseConfigFile`); with none, a default set.
81	    pub tsconfig: Option<Utf8PathBuf>,
82	    /// An explicit `tsc` binary, instead of `node_modules/typescript/bin/tsc` above `project_root`.
83	    pub tsc_path: Option<Utf8PathBuf>,
84	    /// The components to ask about.
85	    pub targets: Vec<Target>,
86	    /// Bound on each request, and on the `tsc` start-up handshake.
87	    pub request_timeout: Duration,
88	    /// The `typescript` versions the checker may report; one that is not among them is a start-up failure.
89	    pub expected_versions: &'static [&'static str],
90	    /// Write every request and its answer here as JSON, to refresh the replay fixture the tests use.
91	    pub record_to: Option<Utf8PathBuf>,
92	    /// Environment for the `tsc` process; the tests use it to pick a replay scenario.
93	    pub extra_env: Vec<(String, String)>,
94	    /// Ask the checker about a component's props, and about the members of each type, last to first. The answer must
95	    /// not change: no id the checker hands out, and so no order of queries, may show in it. The tests set this.
96	    pub reverse_queries: bool,
97	    /// Compiler options of a `tsc` session that is already initialized. A warm checker sets this once so a request
98	    /// only builds its program.
99	    pub(crate) prepared_options: Option<serde_json::Value>,
100	}
101	
102	impl SemanticRequest {
103	    /// A request for `targets` under `project_root`, with a 60 second timeout, the supported versions, and no
104	    /// tsconfig or explicit `tsc` path.
105	    pub fn new(project_root: Utf8PathBuf, targets: Vec<Target>) -> Self {
106	        Self {
107	            project_root,
108	            tsconfig: None,
109	            tsc_path: None,
110	            targets,
111	            request_timeout: Duration::from_secs(60),
112	            expected_versions: SUPPORTED_VERSIONS,
113	            record_to: None,
114	            extra_env: Vec::new(),
115	            reverse_queries: false,
116	            prepared_options: None,
117	        }
118	    }
119	}
120	
121	/// Resolves the request's components with the checker. Blocks; builds its own single-threaded runtime, so it must
122	/// not be called from inside one.
123	pub fn resolve(request: SemanticRequest) -> SemanticOutcome {
124	    let runtime = match tokio::runtime::Builder::new_current_thread().enable_all().build() {
125	        Ok(runtime) => runtime,
126	        Err(error) => return SemanticOutcome::unavailable(format!("could not start an async runtime: {error}")),
127	    };
128	    runtime.block_on(run(request))
129	}
130	
131	/// The exported targets by file, in first-seen order, and an outcome that already holds a fallback for each target
132	/// the checker cannot be asked about.
133	fn group_by_file(request: &SemanticRequest) -> (SemanticOutcome, FxHashMap<&Utf8Path, Vec<&Target>>, Vec<&Utf8Path>) {
134	    let mut outcome = SemanticOutcome::default();
135	    let mut by_file: FxHashMap<&Utf8Path, Vec<&Target>> = FxHashMap::default();
136	    let mut order: Vec<&Utf8Path> = Vec::new();
137	    for target in &request.targets {
138	        if !target.exported {
139	            outcome.fallbacks.push(fallback_of(target, "not exported by its module"));
140	            continue;
141	        }
142	        let group = by_file.entry(target.file_path.as_path()).or_default();
143	        if group.is_empty() {
144	            order.push(target.file_path.as_path());
145	        }
146	        group.push(target);
147	    }
148	    (outcome, by_file, order)
149	}
150	
151	fn supervisor_config(request: &SemanticRequest) -> Result<SupervisorConfig, String> {
152	    let tsc_path = locate::find_tsc(&request.project_root, request.tsc_path.as_deref())?;
153	    let mut config = SupervisorConfig::new(tsc_path, request.project_root.clone(), request.expected_versions);
154	    config.handshake_timeout = request.request_timeout;
155	    config.extra_env.clone_from(&request.extra_env);
156	    Ok(config)
157	}
158	
159	async fn run(request: SemanticRequest) -> SemanticOutcome {
160	    if !request.targets.iter().any(|target| target.exported) {
161	        return group_by_file(&request).0;
162	    }
163	    let config = match supervisor_config(&request) {
164	        Ok(config) => config,
165	        Err(reason) => return SemanticOutcome::unavailable(reason),
166	    };
167	    let supervisor = match Supervisor::spawn(config).await {
168	        Ok(supervisor) => supervisor,
169	        Err(error) => return SemanticOutcome::unavailable(error.to_string()),
170	    };
171	    let outcome = answer_with(&supervisor, &request).await;
172	    supervisor.shutdown().await.ok();
173	    outcome
174	}
175	
176	/// Answers the request's targets with a checker that is already running: one program rooted at their files.
177	async fn answer_with(supervisor: &Supervisor, request: &SemanticRequest) -> SemanticOutcome {
178	    let (mut outcome, by_file, order) = group_by_file(request);
179	    if order.is_empty() {
180	        return outcome;
181	    }
182	    let files: Vec<String> = order.iter().map(|file| file.to_string()).collect();
183	    match session(supervisor, request, &files, &by_file, &order).await {
184	        Ok(mut answered) => {
185	            outcome.components.append(&mut answered.components);
186	            outcome.fallbacks.append(&mut answered.fallbacks);
187	            outcome
188	        }
189	        Err(error) => SemanticOutcome::unavailable(format!("the checker stopped answering: {error}")),
190	    }
191	}
192	
193	async fn session(
194	    supervisor: &Supervisor,
195	    request: &SemanticRequest,
196	    files: &[String],
197	    by_file: &FxHashMap<&Utf8Path, Vec<&Target>>,
198	    order: &[&Utf8Path],
199	) -> Result<SemanticOutcome, CallError> {
200	    let started = std::time::Instant::now();
201	    let opened = match &request.prepared_options {
202	        Some(options) => {
203	            Rpc::open_with(supervisor.client(), request.request_timeout, options, files, request.record_to.is_some())
204	                .await
205	        }
206	        None => {
207	            Rpc::open(
208	                supervisor.client(),
209	                request.request_timeout,
210	                request.tsconfig.as_ref().map(|path| path.as_str()),
211	                files,
212	                request.record_to.is_some(),
213	            )
214	            .await
215	        }
216	    };
217	    let rpc = Arc::new(opened?);
218	    let opened = started.elapsed();
219	    let converter = Converter::new(rpc.clone(), request.reverse_queries);
220	    let limit = Arc::new(Semaphore::new(FILES_IN_FLIGHT));
221	    let interner = Arc::new(PropInterner::default());
222	
223	    let mut tasks = JoinSet::new();
224	    for file in order {
225	        let targets: Vec<Target> = by_file.get(file).into_iter().flatten().map(|target| (*target).clone()).collect();
226	        let (rpc, converter, limit, interner) = (rpc.clone(), converter.clone(), limit.clone(), interner.clone());
227	        tasks.spawn(async move {
228	            let _permit = limit.acquire().await;
229	            answer_file(&rpc, &converter, &interner, targets).await
230	        });
231	    }
232	
233	    let mut outcome = SemanticOutcome::default();
234	    let mut failure = None;
235	    while let Some(joined) = tasks.join_next().await {
236	        match joined {
237	            Ok(Ok(mut answered)) => {
238	                outcome.components.append(&mut answered.components);
239	                outcome.fallbacks.append(&mut answered.fallbacks);
240	            }
241	            Ok(Err(error)) => {
242	                failure = Some(error);
243	                tasks.abort_all();
244	            }
245	            // A panic inside a worker must not silently leave its components structural.
246	            Err(joined) if joined.is_panic() => {
247	                failure = Some(CallError::Fatal("a worker panicked".to_string()));
248	                tasks.abort_all();
249	            }
250	            // A cancelled task is one this loop aborted after a failure.
251	            Err(_cancelled) => {}
252	        }
253	    }
254	    if let Some(error) = failure {
255	        return Err(error);
256	    }
257	
258	    if let (Some(path), Some(recording)) = (&request.record_to, rpc.recording())
259	        && let Ok(json) = serde_json::to_string_pretty(&recording)
260	        && let Err(error) = std::fs::write(path, json)
261	    {
262	        tracing::warn!("could not write the recording to {path}: {error}");
263	    }
264	    tracing::debug!(
265	        requests = ?rpc.calls(),
266	        files = files.len(),
267	        type_memo = ?converter.memo_stats(),
268	        program_ms = opened.as_millis() as u64,
269	        total_ms = started.elapsed().as_millis() as u64,
270	        "semantic backend finished"
271	    );
272	    rpc.release().await;
273	    outcome.components.sort_by(|a, b| (&a.file_path, &a.display_name).cmp(&(&b.file_path, &b.display_name)));
274	    outcome.fallbacks.sort_by(|a, b| (&a.file_path, &a.display_name).cmp(&(&b.file_path, &b.display_name)));
275	    Ok(outcome)
276	}
277	
278	fn fallback_of(target: &Target, reason: &str) -> SemanticFallback {
279	    SemanticFallback {
280	        file_path: target.file_path.clone(),
281	        display_name: target.display_name.clone(),
282	        reason: reason.to_string(),
283	    }
284	}
285	
286	/// A fatal error aborts the run; a call the checker rejected only sends that component to its structural result.
287	async fn answer_file(
288	    rpc: &Rpc,
289	    converter: &Converter,
290	    interner: &PropInterner,
291	    targets: Vec<Target>,
292	) -> Result<SemanticOutcome, CallError> {
293	    let mut outcome = SemanticOutcome::default();
294	    let Some(first) = targets.first() else { return Ok(outcome) };
295	    let exports = match module_exports(rpc, first.file_path.as_str()).await {
296	        Ok(Some(exports)) => exports,
297	        Ok(None) | Err(CallError::Rejected(_)) => {
298	            outcome
299	                .fallbacks
300	                .extend(targets.iter().map(|target| fallback_of(target, "not part of the checker's program")));
301	            return Ok(outcome);
302	        }
303	        Err(fatal) => return Err(fatal),
304	    };
305	
306	    for target in &targets {
307	        let requests = Arc::new(AtomicU64::new(0));
308	        let started = std::time::Instant::now();
309	        let answered =
310	            REQUESTS.scope(requests.clone(), component::props_of(rpc, converter, interner, &exports, target)).await;
311	        tracing::debug!(
312	            component = %target.display_name,
313	            requests = requests.load(Ordering::Relaxed),
314	            ms = started.elapsed().as_millis() as u64,
315	            "semantic component answered"
316	        );
317	        match answered {
318	            Ok(Answer::Props(props)) => outcome.components.push(SemanticComponent {
319	                file_path: target.file_path.clone(),
320	                display_name: target.display_name.clone(),
321	                props,
322	            }),
323	            Ok(Answer::Fallback(reason)) => outcome.fallbacks.push(fallback_of(target, &reason)),
324	            Err(CallError::Rejected(message)) => {
325	                outcome.fallbacks.push(fallback_of(target, &format!("the checker rejected a request: {message}")));
326	            }
327	            Err(fatal) => return Err(fatal),
328	        }
329	    }
330	    Ok(outcome)
331	}
332	
333	async fn module_exports(rpc: &Rpc, file: &str) -> Result<Option<Vec<rpc::SymbolInfo>>, CallError> {
334	    let Some(module) = rpc.source_file_symbol(file).await? else { return Ok(None) };
335	    Ok(Some(rpc.exports_of_module(&module.reference).await?))
336	}
