243	/// One `tsc --api` session bound to a snapshot and project.
244	pub(crate) struct Rpc {
245	    client: Client,
246	    deadline: Duration,
247	    snapshot: u64,
248	    project: String,
249	    /// Every call and its answer, when the caller asked to record a replay fixture.
250	    recording: Option<Mutex<Vec<Value>>>,
251	    calls: Mutex<BTreeMap<String, u64>>,
252	}
253	
254	impl Rpc {
255	    pub(crate) async fn open(
256	        client: Client,
257	        deadline: Duration,
258	        tsconfig: Option<&str>,
259	        root_files: &[String],
260	        record: bool,
261	    ) -> Result<Rpc, CallError> {
262	        let options = Rpc::prepare(&client, deadline, tsconfig).await?;
263	        Rpc::open_with(client, deadline, &options, root_files, record).await
264	    }
265	
266	    /// Initializes the `tsc` session and reads the compiler options, once per process. The beta panics on
267	    /// string-valued enum options such as `target: "es2022"`, so options come from `parseConfigFile`, which yields
268	    /// numeric ones.
269	    pub(crate) async fn prepare(
270	        client: &Client,
271	        deadline: Duration,
272	        tsconfig: Option<&str>,
273	    ) -> Result<Value, CallError> {
274	        let rpc = Rpc {
275	            client: client.clone(),
276	            deadline,
277	            snapshot: 0,
278	            project: String::new(),
279	            recording: None,
280	            calls: Mutex::new(BTreeMap::new()),
281	        };
282	        rpc.call("initialize", Value::Null).await?;
283	        Ok(match tsconfig {
284	            Some(file) => {
285	                let parsed: Value = decode(&rpc.call("parseConfigFile", json!({ "file": file })).await?)?;
286	                parsed.get("options").cloned().unwrap_or_else(default_options)
287	            }
288	            None => default_options(),
289	        })
290	    }
291	
292	    /// A snapshot over `root_files` in a session [`Rpc::prepare`] already initialized.
293	    pub(crate) async fn open_with(
294	        client: Client,
295	        deadline: Duration,
296	        options: &Value,
297	        root_files: &[String],
298	        record: bool,
299	    ) -> Result<Rpc, CallError> {
300	        let mut rpc = Rpc {
301	            client,
302	            deadline,
303	            snapshot: 0,
304	            project: String::new(),
305	            recording: record.then(|| Mutex::new(Vec::new())),
306	            calls: Mutex::new(BTreeMap::new()),
307	        };
308	        let created = rpc
309	            .call(
310	                "createSnapshot",
311	                json!({ "createPrograms": [{ "rootFiles": root_files, "compilerOptions": options }] }),
312	            )
313	            .await?;
314	        let response: SnapshotResponse = decode(&created)?;
315	        let project = response
316	            .projects
317	            .into_iter()
318	            .next()
319	            .ok_or_else(|| CallError::Rejected("createSnapshot returned no project".to_string()))?;
320	        rpc.snapshot = response.snapshot;
321	        rpc.project = project.id;
322	        Ok(rpc)
323	    }
324	
325	    pub(crate) async fn release(&self) {
326	        self.call("release", json!({ "snapshot": self.snapshot })).await.ok();
327	    }
328	
329	    /// The recorded calls as a JSON array, or `None` when recording was off.
330	    pub(crate) fn recording(&self) -> Option<Value> {
331	        let log = self.recording.as_ref()?.lock().ok()?;
332	        Some(Value::Array(log.clone()))
333	    }
334	
335	    /// Requests sent so far, by method.
336	    pub(crate) fn calls(&self) -> BTreeMap<String, u64> {
337	        self.calls.lock().map(|calls| calls.clone()).unwrap_or_default()
338	    }
339	
340	    /// One request, its answer as the JSON text it arrived as: [`decode`] parses it once, into the shape the caller
341	    /// expects.
342	    async fn call(&self, method: &str, params: Value) -> Result<Box<RawValue>, CallError> {
343	        if let Ok(mut calls) = self.calls.lock() {
344	            *calls.entry(method.to_string()).or_default() += 1;
345	        }
346	        REQUESTS.try_with(|count| count.fetch_add(1, std::sync::atomic::Ordering::Relaxed)).ok();
347	        let Some(log) = &self.recording else {
348	            return Ok(self.client.request_raw(method, params, self.deadline).await.map_err(classify)?.result);
349	        };
350	        let answer = self.client.request_raw(method, params.clone(), self.deadline).await.map_err(classify)?;
351	        let result: Value = decode(&answer.result)?;
352	        if let Ok(mut log) = log.lock() {
353	            log.push(json!({ "method": method, "params": params, "result": result }));
354	        }
355	        Ok(answer.result)
356	    }
357	
358	    async fn scoped<T: DeserializeOwned>(&self, method: &str, extra: Value) -> Result<T, CallError> {
359	        decode(&self.scoped_text(method, extra).await?)
360	    }
361	
