// Writes (or, with --check, verifies) the golden files of the deterministic construct suite: for every fixture under
// construct-suite/, the type TypeScript 7.1's checker gives prop `p` of the exported `Row`, normalized as src/oracle.ts
// normalizes it. One program holds all fixtures.
import { existsSync, readFileSync, realpathSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { API } from 'typescript-beta/sync'
import { exportName, propsTypeOf } from './checker-components.ts'
import { listFixtures, PROP, type Fixture, type Golden } from './construct-suite.ts'
import { checkerNormalizer } from './oracle-checker.ts'

const suite = realpathSync(join(import.meta.dirname, '..', 'construct-suite'))
const check = process.argv.includes('--check')

const fixtures = listFixtures(suite)
if (fixtures.length === 0) throw new Error(`no fixtures under ${suite}`)

const api = new API({ cwd: suite })
// `parseConfigFile`, not options by hand: the 7.1 beta's server panics on string-valued enum options (src/oracle.ts).
const { options } = api.parseConfigFile(join(suite, 'tsconfig.json'))
const program = api.createProgram(
  fixtures.map((f) => f.file),
  options,
)
const { checker } = program.getProject()
const norm = checkerNormalizer(checker)

function capture(fixture: Fixture): Golden {
  const moduleSymbol = checker.getSymbolOfSourceFile(fixture.file)
  const exported =
    moduleSymbol && checker.getExportsOfModule(moduleSymbol).find((e: any) => exportName(checker, e) === 'Row')
  if (!exported) throw new Error(`${fixture.id}: no exported Row`)
  const propsType = propsTypeOf(checker, exported)
  const prop = propsType && checker.getPropertyOfType(propsType, PROP)
  if (!prop) throw new Error(`${fixture.id}: Row has no prop ${PROP}`)
  const type = checker.getTypeOfSymbol(prop)
  return { checker: norm(type), text: checker.typeToString(type) }
}

// A unique-symbol key is named `__@tag@<symbol id>` and the id depends on the other files in the program, so adding a
// fixture would change an unrelated golden. Keep the name, drop the id.
const stableSymbolIds = (json: string) => json.replaceAll(/__@(\w+)@\d+/g, '__@$1')

const stale: string[] = []
for (const fixture of fixtures) {
  const text = `${stableSymbolIds(JSON.stringify(capture(fixture), null, 2))}\n`
  const current = existsSync(fixture.golden) ? readFileSync(fixture.golden, 'utf8') : undefined
  if (current === text) continue
  stale.push(fixture.id)
  if (!check) writeFileSync(fixture.golden, text)
}
program.dispose()
api.close()

if (check && stale.length > 0) {
  console.error(
    `golden files out of date (run pnpm --filter caliper-docgen-oracle construct:capture):\n  ${stale.join('\n  ')}`,
  )
  process.exit(1)
}
console.error(`${fixtures.length} fixtures, ${stale.length} ${check ? 'differ' : 'written'}`)
// How the oracles find a component with TypeScript 7.1's checker: the props type of an exported function or class, and
// the name it is exported under. The rule is react-docgen-typescript's (an exported function whose only or `props`
// parameter is the props type), so src/oracle.ts, src/agent-truth.ts and src/reference.ts must all agree on it; they
// share this file so they cannot drift.
import { SignatureKind, SymbolFlags } from 'typescript-beta/sync'

/** The props type of a component export, the way react-docgen-typescript finds it. */
export function propsTypeOf(checker: any, exported: any): any | undefined {
  const symbol = exported.flags & SymbolFlags.Alias ? checker.getAliasedSymbol(exported) : exported
  const type = checker.getTypeOfSymbol(symbol)
  for (const sig of checker.getSignaturesOfType(type, SignatureKind.Call)) {
    const params = sig.getParameters()
    if (params.length === 1 || params[0]?.name === 'props') return checker.getTypeOfSymbol(params[0])
  }
  for (const sig of checker.getSignaturesOfType(type, SignatureKind.Construct)) {
    if (sig.getParameters().length > 1) continue
    const props = checker.getPropertyOfType(sig.getReturnType(), 'props')
    if (props) return checker.getTypeOfSymbol(props)
  }
  return undefined
}

/** A default export is named by what it exports: the aliased declaration, or the function or class itself. */
export function exportName(checker: any, exported: any): string {
  if (exported.name !== 'default') return exported.name
  if (exported.flags & SymbolFlags.Alias) return checker.getAliasedSymbol(exported).name
  return checker.getTypeOfSymbol(exported).getSymbol()?.name ?? 'default'
}

