import { spawn } from "node:child_process"
const [bin, cwd, mode] = process.argv.slice(2)
setTimeout(() => { console.log("TIMEOUT"); process.exit(1) }, 30000)
const child = spawn(bin, ["--api", "--async", "--cwd", cwd], { stdio: ["pipe", "pipe", "inherit"] })
let buf = Buffer.alloc(0), id = 0; const pending = new Map()
child.stdout.on("data", (d) => {
  buf = Buffer.concat([buf, d])
  for (;;) {
    const i = buf.indexOf("\r\n\r\n"); if (i < 0) return
    const len = Number(/Content-Length: (\d+)/i.exec(buf.slice(0, i).toString())[1])
    if (buf.length < i + 4 + len) return
    const msg = JSON.parse(buf.slice(i + 4, i + 4 + len).toString()); buf = buf.slice(i + 4 + len)
    if (msg.id !== undefined && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id) } else console.log("server msg", JSON.stringify(msg).slice(0, 300))
  }
})
const call = (method, params) => new Promise((res) => { const m = { jsonrpc: "2.0", id: ++id, method, params }; pending.set(id, res); const b = Buffer.from(JSON.stringify(m)); child.stdin.write(`Content-Length: ${b.length}\r\n\r\n`); child.stdin.write(b) })
const opts = { jsx: 4, module: 99, moduleResolution: 100, target: 9, strict: true, skipLibCheck: true, noEmit: true }
const show = (label, r) => console.log(label, JSON.stringify(r.error ?? r.result).slice(0, 500))
await call("initialize", null)
const comp = `${cwd}/Poly.tsx`
let t0 = performance.now()
const snap = await call("createSnapshot", { createPrograms: [{ rootFiles: [comp], compilerOptions: opts }] })
console.log("first snapshot ms", (performance.now() - t0).toFixed(1))
let s = snap.result.snapshot, p = snap.result.projects[0].id
const q = (m, x) => call(m, { snapshot: s, project: p, ...x })
const mod = await q("getSymbolOfSourceFile", { file: comp })
const ex = (await q("getExportsOfModule", { symbol: mod.result.reference })).result
const poly = ex.find((e) => e.name === "Poly")
const ty = (await q("getTypeOfSymbol", { symbol: poly.reference })).result
const sigs = (await q("getSignaturesOfType", { type: ty.id, kind: 0 })).result
show("sig", { result: sigs })
const tps = (await q("getTypeParametersOfSignature", { objectId: sigs[0].id })).result
show("tps", { result: tps })
for (const tp of tps) {
  show("default", await q("getDefaultFromTypeParameter", { type: tp.id }))
  show("default2", await q("getDefaultFromTypeParameter", { objectId: tp.id }))
  show("constraint", await q("getConstraintOfTypeParameter", { type: tp.id }))
}
const probe = `${cwd}/__caliper_probe__.ts`
const text = `import type { Poly as __c0 } from "./Poly.tsx"\nexport type __caliper_0 = Parameters<typeof __c0<"div">>[0]\nexport type __caliper_1 = Parameters<typeof __c0<"a">>[0]\nexport type __caliper_2 = Parameters<typeof __c0<Nope>>[0]\n`
t0 = performance.now()
let snap2
if (mode === "update") {
  snap2 = await call("updateSnapshot", { fileSystem: { kind: "layer", files: { [probe]: text } }, createPrograms: [{ rootFiles: [comp, probe], compilerOptions: opts }] })
} else {
  snap2 = await call("createSnapshot", { fileSystem: { kind: "layer", files: { [probe]: text } }, createPrograms: [{ rootFiles: [comp, probe], compilerOptions: opts }] })
}
console.log("probe snapshot ms", (performance.now() - t0).toFixed(1)); show("snap2", snap2)
if (!snap2.result) process.exit(0)
s = snap2.result.snapshot; p = snap2.result.projects[0].id
const psym = await q("getSymbolOfSourceFile", { file: probe }); show("probe sym", psym)
if (!psym.result) process.exit(0)
const diags = await q("getSemanticDiagnostics", { file: probe }); show("diags", diags)
const pex = (await q("getExportsOfModule", { symbol: psym.result.reference })).result
for (const e of pex) {
  const t = await q("getDeclaredTypeOfSymbol", { symbol: e.reference })
  const props = (await q("getPropertiesOfType", { type: t.result.id })).result
  console.log(e.name, t.result.flags, "props", props.length, props.slice(0, 4).map((x) => x.name).join(","))
  const doc = await q("getDocumentationComment", { symbol: props[0].reference }); show("  doc0", doc)
  show("  decl0", { result: props[0].declarations })
}
console.log("total ms", (performance.now() - t0).toFixed(1))
process.exit(0)

