            }),
            Answer::Fallback(reason) => outcome.fallbacks.push(fallback_of(target, &reason)),
            Answer::Instantiate(_) => {
                outcome.fallbacks.push(fallback_of(target, "an instantiation is generic again"));
            }
        }
    }
    Ok(())
